import { test, expect } from '@playwright/test'
import { pathToFileURL } from 'node:url'

// the example pages are generated by the build (rollup.config.mjs): a page that works proves its template, its includes and the bundle
test('generated example page runs Tagify', async ({ page }) => {
    await page.goto(pathToFileURL('docs/examples/dist/basic.html').href)
    await expect(page.locator('tags > tag')).toHaveCount(2)
})
